Here is the root cause:
The bug arises from the use of guest physical addresses that overlap with a reserved address range defined by HyperTransport on AMD processors. This can lead to failures in self-tests when these addresses are accessed, particularly in scenarios where the physical address bits are less than 40 or when using certain processor families that have specific reserved memory regions. The previous implementation did not account for these reserved regions, resulting in potential address conflicts.

Here is the patch:
  */
 struct kvm_vm *vm_create(enum vm_guest_mode mode, uint64_t phy_pages, int perm)
 {
 	struct kvm_vm *vm;

 	pr_debug("%s: mode='%s' pages='%ld' perm='%d'\n", __func__,
 		 vm_guest_mode_string(mode), phy_pages, perm);

 	vm = calloc(1, sizeof(*vm));
 	TEST_ASSERT(vm != NULL, "Insufficient Memory");

 	INIT_LIST_HEAD(&vm->vcpus);
 	vm->regions.gpa_tree = RB_ROOT;
 	vm->regions.hva_tree = RB_ROOT;
 	hash_init(vm->regions.slot_hash);

 	vm->mode = mode;
 	vm->type = 0;

 	vm->pa_bits = vm_guest_mode_params[mode].pa_bits;
 	vm->va_bits = vm_guest_mode_params[mode].va_bits;
 	vm->page_size = vm_guest_mode_params[mode].page_size;
 	vm->page_shift = vm_guest_mode_params[mode].page_shift;

 	/* Setup mode specific traits. */
 	switch (vm->mode) {
 	case VM_MODE_P52V48_4K:
 		vm->pgtable_levels = 4;
 		break;
 	case VM_MODE_P52V48_64K:
 		vm->pgtable_levels = 3;
 		break;
 	case VM_MODE_P48V48_4K:
 		vm->pgtable_levels = 4;
 		break;
 	case VM_MODE_P48V48_64K:
 		vm->pgtable_levels = 3;
 		break;
 	case VM_MODE_P40V48_4K:
 		vm->pgtable_levels = 4;
 		break;
 	case VM_MODE_P40V48_64K:
 		vm->pgtable_levels = 3;
 		break;
 	case VM_MODE_PXXV48_4K:
 #ifdef __x86_64__
 		kvm_get_cpu_address_width(&vm->pa_bits, &vm->va_bits);
 		/*
 		 * Ignore KVM support for 5-level paging (vm->va_bits == 57),
 		 * it doesn't take effect unless a CR4.LA57 is set, which it
 		 * isn't for this VM_MODE.
 		 */
 		TEST_ASSERT(vm->va_bits == 48 || vm->va_bits == 57,
 			    "Linear address width (%d bits) not supported",
 			    vm->va_bits);
 		pr_debug("Guest physical address width detected: %d\n",
 			 vm->pa_bits);
 		vm->pgtable_levels = 4;
 		vm->va_bits = 48;
 #else
 		TEST_FAIL("VM_MODE_PXXV48_4K not supported on non-x86 platforms");
 #endif
 		break;
 	case VM_MODE_P47V64_4K:
 		vm->pgtable_levels = 5;
 		break;
 	case VM_MODE_P44V64_4K:
 		vm->pgtable_levels = 5;
 		break;
 	default:
 		TEST_FAIL("Unknown guest mode, mode: 0x%x", mode);
 	}

 #ifdef __aarch64__
